const WRITE_OPERATIONS = new Set([
  'BARCODES_ALLOCATE','CARD_UPLOAD','CARD_UPDATE','CARD_UPLOAD_ADD','MEDIA_UPLOAD_FILE','MEDIA_SAVE',
  'PRICES_UPLOAD_PRODUCT','PRICES_UPLOAD_SIZE','PRICES_UPLOAD_CLUB_DISCOUNT','STOCKS_WRITE',
