function normalizedFailure(error, input, inputIndex) {
  const details = error?.details && typeof error.details === 'object' ? error.details : {};
  if (['NOT_SENT','UNKNOWN','RESPONDED'].includes(String(details.deliveryState || ''))) {
    return { json: { ...details, ok: false, requestRef: input.requestRef, operation: input.operation, inputIndex }, pairedItem: { item: inputIndex } };
  }
  const code = String(error?.code || 'MERCHROUTE_GATEWAY_UNAVAILABLE').toUpperCase();
