  const deliveryState = notSent ? 'NOT_SENT' : 'UNKNOWN';
  const retryClass = beforeSend ? 'PERMANENT' : (deliveryState === 'UNKNOWN' && WRITE_OPERATIONS.has(input.operation) ? 'READBACK_REQUIRED' : 'RETRYABLE');
  return { json: {
    ok: false, statusCode: Number(error?.httpStatus || 0), body: {}, deliveryState, retryClass,
    requestRef: input.requestRef, operation: input.operation, inputIndex,
    error: { code, message: String(error?.message || 'MerchRoute WB gateway 不可用').slice(0, 1000) },
  }, pairedItem: { item: inputIndex } };
}
