      if (!input.requestRef || input.requestRef.length > 240 || !/^[A-Za-z0-9._:|-]+$/.test(input.requestRef)) throw contractError('REQUEST_REF_INVALID', 'requestRef 格式无效');
      if (input.taskId && input.storeId) throw contractError('GATEWAY_SCOPE_AMBIGUOUS', 'taskId/storeId 不能同时提交');
